const {chromium}=require(process.cwd()+'/node_modules/playwright');const sharp=require(process.cwd()+'/node_modules/sharp');const fs=require('fs');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});await p.goto('http://localhost:32121/tools/visualization',{waitUntil:'networkidle'});const dir='docs/visualization/20260920/evidence/png';fs.mkdirSync(dir,{recursive:true});const reports=[];for(const [i,name] of ['柴染棕','橙绯红','淡藤萝紫','瓜瓤粉','蓝墨茶','棉絮灰','珊瑚朱','杏叶黄','中国红'].entries()){await p.getByRole('button',{name,exact:true}).click();const event=p.waitForEvent('download');await p.getByRole('button',{name:'PNG',exact:true}).click();const data=fs.readFileSync(await(await event).path());fs.writeFileSync(`${dir}/${i}.png`,data);const metadata=await sharp(data).metadata();const stats=await sharp(data).stats();if(metadata.width!==2125||metadata.height!==2125||stats.channels[0].stdev<10)throw Error('Invalid PNG');reports.push({name,width:metadata.width,height:metadata.height,bytes:data.length,stdev:stats.channels[0].stdev});}fs.writeFileSync(dir+'/report.json',JSON.stringify(reports,null,2));await b.close()})();
